package decision

import (
	"encoding/json"
	"os"
	"reflect"
	"testing"
)

// Parity with the JS port (server/plan/replan.js): the vectors are generated by tools/gen_replan_vectors.mjs; inputs use the Go field names.
// Skipped when the repo's server/ directory is not next to the Go module (for example in a module-only checkout).
func TestReplanParityVectors(t *testing.T) {
	raw, err := os.ReadFile("../../../server/plan/vectors/replan.json")
	if err != nil {
		t.Skip("vectors not found: " + err.Error())
	}
	var cases []struct {
		Name      string          `json:"name"`
		Input     ReplanInput     `json:"input"`
		Proposals json.RawMessage `json:"proposals"`
		Caps      [2]float64      `json:"caps"`
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		got := EvaluateReplan(c.Input)
		gb, _ := json.Marshal(got)
		var g, w any
		_ = json.Unmarshal(gb, &g)
		_ = json.Unmarshal(c.Proposals, &w)
		if len(got) == 0 { // Go returns nil -> null; the JS port returns []
			g = []any{}
		}
		if !reflect.DeepEqual(g, w) {
			t.Fatalf("%s: proposals differ\n go: %s\n js: %s", c.Name, gb, c.Proposals)
		}
		sw, sl := ApplyCaps(c.Input)
		if sw != c.Caps[0] || sl != c.Caps[1] {
			t.Fatalf("%s: caps differ go=(%v,%v) js=%v", c.Name, sw, sl, c.Caps)
		}
	}
}
